<script setup lang="ts">
import AdminOdds from './AdminOdds.vue'
import AdminPromotions from './AdminPromotions.vue'
import AdminGameControl from './AdminGameControl.vue'
import {ref,computed,onMounted,watch,nextTick} from 'vue'
import {LayoutDashboard,Users,SlidersHorizontal,Wallet,FileText,Gift,History,Search,RefreshCw,X,ChevronLeft,ChevronRight,ShieldCheck} from 'lucide-vue-next'
import {api,user,site,refreshSite,refreshAccount,money,cents,datetime,key,labels,sessionNames,loadSessionNames,type SiteSettings} from '../api/account'
const emit=defineEmits<{login:[];notify:[message:string]}>()
const tabs=[{id:'game-control',label:'游戏控制',icon:SlidersHorizontal},{id:'promotions',label:'活动管理',icon:Gift},{id:'odds',label:'赔率设置',icon:SlidersHorizontal},{id:'overview',label:'运营概览',icon:LayoutDashboard},{id:'users',label:'用户列表',icon:Users},{id:'requests',label:'资金审核',icon:Wallet},{id:'orders',label:'订单管理',icon:FileText},{id:'settings',label:'玩法与分销',icon:SlidersHorizontal},{id:'commissions',label:'佣金明细',icon:Gift},{id:'ledger',label:'余额流水',icon:History},{id:'audit',label:'操作日志',icon:ShieldCheck}]
const tab=ref('overview'),rows=ref<any[]>([]),overview=ref<Record<string,number>>({}),total=ref(0),page=ref(1),query=ref(''),loading=ref(false),busy=ref(false),error=ref(''),cfg=ref<SiteSettings|null>(null),rates=ref<number[]>([0,0,0]),unitPrices=ref<string[]>([]),stakeLimits=ref<string[]>([]),registrationBonus=ref('0.00'),issueLimits=ref<string[]>([])
const action=ref(''),target=ref<any>(null),amount=ref(''),note=ref(''),decision=ref('approved'),actionError=ref(''),requestKey=ref(''),actionResult=ref(''),dialog=ref<HTMLElement|null>(null)
let version=0,priorFocus:HTMLElement|null=null
const isAdmin=computed(()=>user.value?.role==='admin')
const title=computed(()=>tabs.find(t=>t.id===tab.value)?.label)
async function load(){if(!isAdmin.value||['odds','promotions','game-control'].includes(tab.value))return;const current=++version;loading.value=true;error.value='';try{if(tab.value==='settings'){const c=await api<SiteSettings>('/admin/settings');if(current!==version)return;cfg.value=c;issueLimits.value=c.plays.map(p=>((p.user_issue_limit_cents??2000000)/100).toFixed(2));registrationBonus.value=((c.registration_bonus_cents??0)/100).toFixed(2);rates.value=c.commission_bps.map(n=>n/100);unitPrices.value=c.plays.map(p=>(p.unit_cents/100).toFixed(2));stakeLimits.value=c.plays.map(p=>(p.max_stake_cents/100).toFixed(2))}else{const d=await api<any>(`/admin/${tab.value}?page=${page.value}&q=${encodeURIComponent(query.value)}`);if(current!==version)return;if(tab.value==='overview')overview.value=d;else{rows.value=d.items;total.value=d.total}}}catch(e){if(current===version)error.value=(e as Error).message}finally{if(current===version)loading.value=false}}
function changeTab(id:string){tab.value=id;page.value=1;query.value='';rows.value=[];void load()}
onMounted(()=>{void loadSessionNames().catch(()=>{});void load()});watch(isAdmin,()=>void load())
async function saveSettings(){if(!cfg.value||busy.value)return;busy.value=true;error.value='';try{const next=JSON.parse(JSON.stringify(cfg.value)) as SiteSettings;next.registration_bonus_cents=cents(registrationBonus.value);next.commission_bps=rates.value.map(n=>cents(String(n))) as [number,number,number];next.plays.forEach((p,i)=>{p.unit_cents=cents(unitPrices.value[i]??'');p.max_stake_cents=cents(stakeLimits.value[i]??'');p.user_issue_limit_cents=cents(issueLimits.value[i]??'')});await api('/admin/settings','PUT',next);await refreshSite();emit('notify','玩法、三级比例和站点设置已保存')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function openAction(name:string,row:any){priorFocus=document.activeElement as HTMLElement;action.value=name;target.value=row;amount.value=name==='settle'?'0.00':'';note.value='';decision.value=name==='settle'?(row.market_id?'refunded':'settled'):'approved';actionError.value='';requestKey.value=key();actionResult.value='';await nextTick();dialog.value?.focus();if(name==='settle'){actionResult.value='正在读取本期结果…';try{const r=await api<any>(`/sessions/${row.session_id}/draws/${row.issue}`);if(action.value===name&&target.value?.id===row.id)actionResult.value=`开奖结果：${r.display_numbers.join(' · ')}${r.sum!==undefined?'，和值 '+r.sum:''}（${r.origin==='scheduled'?'定时生成':'模拟历史，不可结算'}）`}catch{if(action.value===name&&target.value?.id===row.id)actionResult.value='本期尚无开奖结果，可等待开奖或撤销订单。'}}}
function closeAction(){if(busy.value)return;action.value='';priorFocus?.focus()}
function trap(e:KeyboardEvent){if(e.key!=='Tab')return;const els=dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,textarea');if(!els?.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===dialog.value)){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
async function submitAction(){if(busy.value)return;busy.value=true;actionError.value='';try{const id=target.value.id;if(action.value==='balance')await api(`/admin/users/${id}/balance`,'POST',{amount_cents:cents(amount.value),note:note.value,key:requestKey.value});else if(action.value==='status')await api(`/admin/users/${id}`,'PATCH',{status:target.value.status==='active'?'disabled':'active'});else if(action.value==='review')await api(`/admin/requests/${id}/review`,'POST',{decision:decision.value,note:note.value});else if(action.value==='settle')await api(`/admin/orders/${id}/settle`,'POST',{decision:decision.value,note:note.value,payout_cents:decision.value==='refunded'?0:cents(amount.value)});action.value='';priorFocus?.focus();emit('notify','操作成功，已记录操作日志');await Promise.all([load(),refreshAccount()])}catch(e){actionError.value=(e as Error).message}finally{busy.value=false}}
const metricCards=computed(()=>[{label:'账户总数',value:overview.value.users??0,hint:'会员与管理员'},{label:'用户可用余额',value:money(overview.value.balance_cents),hint:`冻结 ${money(overview.value.frozen_cents)}`},{label:'待审核申请',value:overview.value.pending_requests??0,hint:'充值 / 提现人工核对'},{label:'待结算订单',value:overview.value.pending_orders??0,hint:`累计订单 ${overview.value.orders??0}`},{label:'有效投注总额',value:money(overview.value.valid_stake_cents),hint:'已结算且未撤销'},{label:'已生成佣金',value:money(overview.value.commission_cents),hint:'三级佣金累计'}])
</script>
<template><div class="admin-page"><div class="page-heading"><div><p class="section-eyebrow">STARLIGHT · ADMIN CONSOLE</p><h1>管理工作台</h1><p>账户、玩法、资金与团队，清晰掌握。</p></div><span class="admin-security"><ShieldCheck :size="17"/>管理员权限</span></div><div v-if="!isAdmin" class="account-empty"><ShieldCheck :size="42"/><h2>管理员专属工作台</h2><p>{{user?'当前账户没有管理权限。':'请使用管理员账户登录。'}}</p><button v-if="!user" class="primary-button" @click="emit('login')">管理员登录</button></div><template v-else><nav class="admin-tabs" aria-label="后台功能"><button v-for="t in tabs" :class="{active:tab===t.id}" @click="changeTab(t.id)"><component :is="t.icon" :size="17"/>{{t.label}}</button></nav><div v-if="error" class="form-error" role="alert">{{error}}</div><div v-if="!['promotions','game-control'].includes(tab)" class="admin-toolbar"><h2>{{title}}</h2><form v-if="!['settings','overview','odds','promotions','game-control'].includes(tab)" class="admin-search" @submit.prevent="page=1;load()"><Search :size="16"/><input v-model="query" placeholder="搜索用户名、编号或状态" aria-label="搜索管理记录"/><button type="submit">搜索</button></form><button class="secondary-button" :disabled="loading" @click="load"><RefreshCw :size="15"/>刷新</button></div><div v-if="loading" class="loading-line" role="status">正在加载…</div>
 <AdminGameControl v-if="tab==='game-control'" @settings="changeTab('settings')" @odds="changeTab('odds')"/><AdminPromotions v-else-if="tab==='promotions'" @notify="emit('notify',$event)"/><AdminOdds v-else-if="tab==='odds'" @notify="emit('notify',$event)"/>
 <template v-else-if="tab==='overview'"><div class="metric-grid admin-metrics"><article v-for="c in metricCards"><small>{{c.label}}</small><strong>{{c.value}}</strong><span>{{c.hint}}</span></article></div><section class="admin-welcome surface"><div><span class="badge">管理提醒</span><h2>从清晰的记录开始</h2><p>充值、提现需人工核对；两面和定位订单自动结算。每次调账、审核和设置修改都会进入操作日志。</p><p>三级佣金按订单保存的比例计算，默认比例为0，可在“玩法与分销”中启用。</p></div><div class="admin-shortcuts"><button @click="changeTab('requests')">处理资金申请 <ChevronRight :size="16"/></button><button @click="changeTab('settings')">配置玩法与三级佣金 <ChevronRight :size="16"/></button></div></section></template>
 <form v-else-if="tab==='settings'&&cfg" class="settings-form" @submit.prevent="saveSettings"><section class="surface"><div class="surface-heading"><div><h3>三级邀请佣金</h3><p class="form-hint">用户可同时拥有邀请人和下级。已结算有效投注分别向上三级计佣，总比例不可超过100%。</p></div><span class="badge">新订单生效</span></div><div class="settings-rates"><label v-for="(_,i) in rates">{{['一级直邀','二级团队','三级团队'][i]}}比例（%）<input v-model.number="rates[i]" type="number" min="0" max="100" step="0.01" required/></label></div><p class="form-hint">撤销不计佣；每级佣金计算到分、向下取整。会员在佣金页领取到余额。旧订单继续使用原比例。</p></section><section class="surface"><h3>玩法与场次</h3><p class="form-hint">单用户单期上限按同一用户、同一场次、同一期累计，两面、常规和单式合并；撤销退款释放额度。启停控制新订单提交，不影响开奖与历史查询。所有场次固定在整分前10秒封盘、后05秒开奖，封盘窗口15秒。</p><div class="data-table-wrap"><table class="data-table settings-table"><thead><tr><th>游戏场次</th><th>接单</th><th>起投金额（元）</th><th>单笔上限（元）</th><th>单用户单期上限（元）</th><th>旧版最大倍数</th><th>封盘与开奖</th></tr></thead><tbody><tr v-for="(p,i) in cfg.plays" :key="p.session_id"><td>{{sessionNames[p.session_id]||p.session_id}}</td><td><input type="checkbox" v-model="p.enabled" :aria-label="`${p.session_id}启用`"/></td><td><input v-model="unitPrices[i]" inputmode="decimal" required :aria-label="`${p.session_id}单注金额`"/></td><td><input v-model="stakeLimits[i]" inputmode="decimal" required :aria-label="`${p.session_id}单笔上限`"/></td><td><input v-model="issueLimits[i]" inputmode="decimal" required :aria-label="`${p.session_id}单用户单期上限`"/></td><td><input v-model.number="p.max_multiplier" type="number" min="1" max="999" required :aria-label="`${p.session_id}最大倍数`"/></td><td><span>前10秒封盘<small>后05秒开奖 · 间隔15秒</small></span></td></tr></tbody></table></div></section><section class="surface form-stack"><h3>站点设置</h3><label class="checkbox-label"><input type="checkbox" v-model="cfg.registration"/>开放新用户注册</label><label class="checkbox-label"><input type="checkbox" v-model="cfg.invite_required" :disabled="busy"/>注册必须填写邀请码</label><p class="form-hint">开启后，新用户须填写有效邀请码才能注册；关闭后邀请码选填。</p><label>新用户注册赠送金额（元）<input v-model="registrationBonus" inputmode="decimal" required :disabled="busy"/></label><p class="form-hint">用于开发测试，注册成功后一次性计入余额；设为0关闭赠送，已有账户不补发。</p><label>大厅公告<textarea v-model="cfg.announcement" rows="3" maxlength="500"/></label></section><div class="settings-save"><span>设置保存后立即生效</span><button class="primary-button" :disabled="busy">{{busy?'保存中…':'保存全部设置'}}</button></div></form>
 <section v-else-if="!['settings','overview','odds','promotions','game-control'].includes(tab)" class="surface admin-data"><p class="mobile-table-hint">左右滑动表格，查看完整信息与操作</p><div class="data-table-wrap"><table class="data-table"><thead><tr v-if="tab==='users'"><th>用户</th><th>角色 / 状态</th><th>可用 / 冻结</th><th>邀请码 / 邀请人</th><th>操作</th></tr><tr v-else-if="tab==='requests'"><th>申请人 / 编号</th><th>类型 / 金额</th><th>说明</th><th>状态 / 时间</th><th>操作</th></tr><tr v-else-if="tab==='orders'"><th>用户 / 订单</th><th>场次 / 期号 / 号码</th><th>金额 / 派彩</th><th>状态</th><th>操作</th></tr><tr v-else-if="tab==='commissions'"><th>佣金 / 时间</th><th>受益人</th><th>来源 / 层级</th><th>有效投注 / 比例</th><th>佣金 / 状态</th></tr><tr v-else-if="tab==='ledger'"><th>流水 / 时间</th><th>用户</th><th>类型 / 说明</th><th>变动</th><th>可用 / 冻结</th></tr><tr v-else><th>时间</th><th>操作人ID</th><th>操作</th><th>目标</th><th>详情</th></tr></thead><tbody>
 <tr v-for="r in rows" :key="r.id"><template v-if="tab==='users'"><td><strong>{{r.username}}</strong><small>{{datetime(r.created_at)}}</small><small class="id-text" :title="r.id">{{r.id}}</small></td><td>{{r.role==='admin'?'管理员':'会员'}}<small><span class="badge" :class="r.status">{{labels[r.status]}}</span></small></td><td>{{money(r.balance_cents)}}<small>冻结 {{money(r.frozen_cents)}}</small></td><td>{{r.invite_code}}<small class="id-text" :title="r.inviter_id">{{r.inviter_username||'无上级邀请人'}}</small></td><td><div class="table-actions"><button @click="openAction('balance',r)">调整余额</button><button v-if="r.role!=='admin'" @click="openAction('status',r)">{{r.status==='active'?'停用':'恢复'}}</button></div></td></template>
 <template v-else-if="tab==='requests'"><td><strong>{{r.username}}</strong><small>#{{Number(r.id)}}</small></td><td>{{labels[r.kind]}}<small>{{money(r.amount_cents)}}</small></td><td class="note-cell">{{r.note}}<small>{{r.review_note}}</small></td><td><span class="badge" :class="r.status">{{labels[r.status]}}</span><small>{{datetime(r.created_at)}}</small></td><td><button v-if="r.status==='pending'" class="text-button" @click="openAction('review',r)">审核申请</button><span v-else>已处理</span></td></template>
 <template v-else-if="tab==='orders'"><td><strong>{{r.username}}</strong><small>#{{Number(r.id)}} · {{datetime(r.created_at)}}</small></td><td>{{r.game_name}} · {{r.session_name}}<small>{{r.issue}}</small><small>{{r.market_name||r.numbers.join(' · ')}}</small></td><td>{{money(r.cost_cents)}}<small>派彩 {{money(r.payout_cents)}}</small><small v-if="r.odds_milli">赔率 {{(r.odds_milli/1000).toFixed(3)}} · {{({win:'中奖',lose:'未中',push:'退本'} as Record<string,string>)[r.outcome]||'待开奖'}}</small></td><td><span class="badge" :class="r.status">{{labels[r.status]}}</span><small class="note-cell">{{r.note}}</small></td><td><button v-if="r.status==='pending'" class="text-button" @click="openAction('settle',r)">{{r.market_id?'自动结算 / 撤销':'人工结算 / 撤销'}}</button><span v-else>已处理</span></td></template>
 <template v-else-if="tab==='commissions'"><td>#{{Number(r.id)}}<small>{{datetime(r.created_at)}}</small></td><td :title="r.user_id">{{r.username||r.user_id}}<small class="id-text">{{r.user_id}}</small></td><td>{{r.from_username}}<small>{{r.level}}级 · 订单{{Number(r.order_id)}}</small></td><td>{{money(r.valid_stake_cents)}}<small>{{r.rate_bps/100}}%</small></td><td class="positive">{{money(r.amount_cents)}}<small><span class="badge" :class="r.status">{{labels[r.status]}}</span></small></td></template>
 <template v-else-if="tab==='ledger'"><td>#{{Number(r.id)}}<small>{{datetime(r.created_at)}}</small></td><td :title="r.user_id">{{r.username||r.user_id}}<small class="id-text">{{r.user_id}}</small></td><td>{{labels[r.kind]||r.kind}}<small class="note-cell">{{r.note}}</small></td><td :class="r.amount_cents>0?'positive':''">{{r.amount_cents>0?'+':''}}{{money(r.amount_cents)}}</td><td>{{money(r.balance_cents)}}<small>冻结 {{money(r.frozen_cents)}}</small></td></template>
 <template v-else><td>{{datetime(r.created_at)}}</td><td class="id-text" :title="r.actor">{{r.actor}}</td><td>{{r.action}}</td><td class="id-text" :title="r.target">{{r.target}}</td><td><details><summary>查看详情</summary><pre class="audit-detail">{{r.detail}}</pre></details></td></template></tr><tr v-if="!rows.length&&!loading"><td :colspan="tab==='audit'?5:5" class="empty-copy">暂无匹配记录</td></tr></tbody></table></div><div class="admin-pagination"><span>共 {{total}} 条 · 第 {{page}} / {{Math.max(1,Math.ceil(total/20))}} 页</span><div><button :disabled="page<=1||loading" aria-label="后台上一页" @click="page--;load()"><ChevronLeft :size="17"/></button><button :disabled="page*20>=total||loading" aria-label="后台下一页" @click="page++;load()"><ChevronRight :size="17"/></button></div></div></section>
 </template><div v-if="action" class="modal-overlay" @click.self="closeAction" @keydown.esc="closeAction" @keydown="trap"><section class="modal admin-action" ref="dialog" role="dialog" aria-modal="true" aria-labelledby="admin-action-title" tabindex="-1"><button class="modal-close icon-button" aria-label="关闭管理操作" :disabled="busy" @click="closeAction"><X/></button><h2 id="admin-action-title">{{({balance:'调整账户余额',status:'变更用户状态',review:'审核资金申请',settle:'人工结算订单'} as Record<string,string>)[action]}}</h2><p>操作对象：<strong>{{target.username}}</strong><template v-if="action==='review'"> · {{labels[target.kind]}} {{money(target.amount_cents)}}</template><template v-if="action==='settle'"> · {{target.game_name}} · {{target.issue}}</template></p><form class="form-stack" @submit.prevent="submitAction"><template v-if="action==='status'"><p>确认{{target.status==='active'?'停用':'恢复'}}该账户？停用会立即终止所有登录会话，余额与记录保留。</p></template><template v-else-if="action==='balance'"><label>调整金额（元）<input v-model="amount" required inputmode="decimal" placeholder="正数增加，负数扣减"/></label><p class="form-hint">当前余额 {{money(target.balance_cents)}}。余额调整会保留原因及操作人。</p></template><template v-else-if="action==='review'"><label>审核结果<select v-model="decision"><option value="approved">通过</option><option value="rejected">驳回</option></select></label><p class="form-hint">{{target.kind==='deposit'?'仅在确认款项到账后通过，审核通过将增加余额。':'仅在确认外部出款完成后通过；驳回将退回冻结金额。'}}</p><p class="form-hint">申请说明：{{target.note}}</p></template><template v-else-if="action==='settle'"><p class="form-hint">{{actionResult}}</p><p>所选号码：{{target.market_name||target.numbers.join(' · ')}} · {{target.multiplier}}倍 · 投注 {{money(target.cost_cents)}}</p><label>处理方式<select v-model="decision"><option v-if="!target.market_id" value="settled">完成结算（计入有效投注）</option><option value="refunded">撤销退回（不计佣）</option></select></label><label v-if="decision==='settled'">核定派彩金额（元）<input v-model="amount" required inputmode="decimal" placeholder="未中奖填0"/></label><p class="form-hint">{{target.market_id?'该订单由系统按下单时的赔率自动结算，此处只可撤销退本；已结算订单不可撤销。':'旧版整注订单需人工核对派彩。已完成订单不可重复处理。'}}</p></template><label v-if="action!=='status'">操作说明<textarea v-model="note" required minlength="2" maxlength="500" rows="3" placeholder="填写审核依据或调整原因"/></label><div v-if="actionError" class="form-error" role="alert">{{actionError}}</div><button class="primary-button" :disabled="busy">{{busy?'处理中…':'确认并记录操作'}}</button></form></section></div></div></template>
